package com.securedeploy.editing;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WorkspacePatchPlanTest {
 final ObjectMapper json=new ObjectMapper();
 WorkspacePatch.View view()throws Exception{return json.readValue("""
 {"id":"proposal","fileId":"file-a","revision":1,"originalHash":"original","startLine":3,"before":"{ready:true,x:process.env.API_SECRET}","method":"AI_PLAN_SERVER_AST","context":{"code":"import framework from 'express'; const app=framework(); app.get('/health',(a,b)=>{return b.json({ready:true,x:process.env.API_SECRET});});","startLine":3,"endLine":3,"endpoint":"GET /health","sources":[{"line":3,"column":22}],"sink":{"line":3,"column":1},"removedFields":["x"],"preservedFields":["ready"],"bindings":[{"findingId":"finding","sourceId":"source-a","field":"x","source":{"line":3,"column":22},"sink":{"line":3,"column":1},"startOffset":20,"endOffset":40,"expressionHash":"expr"}]}}
 """,WorkspacePatch.View.class);}
 WorkspacePatchPlan.Output result(WorkspacePatch.View v,String decision,List<WorkspacePatchPlan.Operation>ops){return new WorkspacePatchPlan.Output(decision,v.plan().objectId(),ops,"통제 수정 계획",List.of("API 계약 확인"),List.of("운영 미검증"));}
 @Test void closedPlanUsesOpaqueScopedTargetsAndExactRequiredSet()throws Exception{var v=view();var f=v.plan().requiredFields().get(0);assertTrue(f.fieldId().matches("[a-f0-9]{64}"));assertNotEquals(f.sourceId(),f.fieldId());var valid=new WorkspacePatchPlan.Operation(f.fieldId(),WorkspacePatchPlan.OPERATION);assertDoesNotThrow(()->WorkspacePatchPlan.validate(result(v,"PATCH",List.of(valid)),v));for(var ops:List.of(List.<WorkspacePatchPlan.Operation>of(),List.of(valid,valid),List.of(new WorkspacePatchPlan.Operation("invented-source-or-normal-field",WorkspacePatchPlan.OPERATION)),List.of(new WorkspacePatchPlan.Operation(f.fieldId(),"REWRITE_CODE"))))assertThrows(IllegalArgumentException.class,()->WorkspacePatchPlan.validate(result(v,"PATCH",ops),v));assertDoesNotThrow(()->WorkspacePatchPlan.validate(result(v,"NEEDS_REVIEW",List.of()),v));assertThrows(IllegalArgumentException.class,()->WorkspacePatchPlan.validate(result(v,"NEEDS_REVIEW",List.of(valid)),v));assertThrows(IllegalArgumentException.class,()->WorkspacePatchPlan.validate(new WorkspacePatchPlan.Output("PATCH","other-response",List.of(valid),"説明",List.of("確認"),List.of("未確認")),v));}
 @Test void schemaHasNoCodePathsOrCoordinatesAndAllObjectPropertiesAreClosed()throws Exception{var schema=json.valueToTree(WorkspacePatchPlan.schema());assertFalse(schema.path("additionalProperties").asBoolean(true));assertEquals(schema.path("properties").size(),schema.path("required").size());assertFalse(schema.at("/properties/operations/items/additionalProperties").asBoolean(true));assertEquals(2,schema.at("/properties/operations/items/required").size());for(String field:List.of("replacement","filePath","sourceId","startLine","astPosition"))assertFalse(schema.path("properties").has(field));var v=view();var payload=json.readTree(WorkspacePatchPlan.prompt(v,json).untrustedData());assertFalse(payload.has("untrustedCode"));assertEquals(v.contextHash(),payload.path("contextHash").asText());assertNotEquals(v.context().fingerprint(),v.contextHash());}
 @Test void parserRejectsUnsupportedShapeAndNeverNormalizesLegacyCodeOutput()throws Exception{for(String name:List.of("A","B")){try(var in=getClass().getResourceAsStream("/patch03/live02/"+name+"_MODEL_OUTPUT.json")){assertThrows(IllegalArgumentException.class,()->WorkspacePatchPlan.parse(json.readTree(in)));}}var v=view();var valid=json.valueToTree(result(v,"NEEDS_REVIEW",List.of()));assertNotNull(WorkspacePatchPlan.parse(valid));for(String field:List.of("replacement","sourceId","filePath","astPosition")){var bad=((com.fasterxml.jackson.databind.node.ObjectNode)valid).deepCopy();bad.put(field,"invented");assertThrows(IllegalArgumentException.class,()->WorkspacePatchPlan.parse(bad));}}
}
